{The improved heuristic directly multiplies the inverse-square distance penalty with the safety factors, avoiding redundant normalization while strictly rewarding ~180-degree turns and penalizing infeasible battery paths.}

```python
import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    eps = 1e-4
    turn_score = 1.0 / (1.0 + np.exp(3.0 * (turn_deg - 180.0)))
    safe_term = np.exp(-5.0 * (1.0 - fits)) + 0.3 * energy_left_frac
    depot_influence = 1.0 / np.minimum(depot_dist_m + 50.0, 200.0)
    return (1.0 / ((dist_m + eps) ** 2)) * turn_score * (safe_term + 0.3 * depot_influence)
